package com.example.a3_1mod2casestudy2.utils

class PromptEvaluator {

    /**
     * Compares outputs generated by Zero-Shot, Few-Shot, and Structured Prompt strategies.
     */
    fun comparePrompts(
        zeroShotResponse: String,
        fewShotResponse: String,
        structuredResponse: String
    ): String {
        val zeroShotWordCount = zeroShotResponse.split("\\s+".toRegex()).size
        val fewShotWordCount = fewShotResponse.split("\\s+".toRegex()).size
        val structuredWordCount = structuredResponse.split("\\s+".toRegex()).size

        val isStructuredJsonValid = structuredResponse.trim().startsWith("{") && structuredResponse.trim().endsWith("}")
        val followsFewShotBullets = fewShotResponse.contains("-") || fewShotResponse.contains(":")

        return """
            ==================================================
                    PROMPT STRATEGY EVALUATION METRICS
            ==================================================
            
            1. ZERO-SHOT PROMPT EVALUATION:
               - Word Count: $zeroShotWordCount
               - Format Adherence: Moderate (Freeform narrative text)
               - Precision: General / Surface-level
               - Hallucination Risk: Medium (No boundary constraints)
               
            2. FEW-SHOT PROMPT EVALUATION:
               - Word Count: $fewShotWordCount
               - Pattern Matching: ${if (followsFewShotBullets) "HIGH (Matched few-shot bullet style)" else "MODERATE"}
               - Detail Density: High (Informed by example structure)
               - Hallucination Risk: Low-Medium
               
            3. STRUCTURED PROMPT EVALUATION:
               - Word Count: $structuredWordCount
               - JSON Output Schema Valid: ${if (isStructuredJsonValid) "YES (Strict JSON structure)" else "NO"}
               - Machine-Parseable: ${if (isStructuredJsonValid) "HIGH (Direct REST API / Data Pipeline Ready)" else "LOW"}
               - Hallucination Risk: LOWEST (Bounded by explicit schema & rules)

            --------------------------------------------------
            KEY CONCLUSION:
            - Zero-Shot is fast for simple Q&A but inconsistent in structure.
            - Few-Shot provides consistent formatting and style via pattern matching.
            - Structured Prompting guarantees exact schema adherence and machine parseability!
            ==================================================
        """.trimIndent()
    }
}
